//! The VQS-1 conformance suite (`spec/VQS-1.md` section 11).
//!
//! * [`cases`]: the cases of suite v1, generated by code from fixed Philox
//!   streams, so the inputs themselves are identical on every platform.
//! * [`runner`]: runs the cases on a backend, compares the SHA3-256 of every
//!   output with the committed expected vectors, and writes a report that
//!   contains no timing or platform data, so reports from different
//!   machines compare byte for byte.
//!
//! A backend conforms when it reproduces every case. Partial conformance is
//! non-conformance.

pub mod cases;
pub mod runner;

/// Name of this suite; it changes whenever a case or an expected byte does.
pub const SUITE: &str = "vqs1-v1";
